import test from'node:test';import assert from'node:assert/strict';import{Automaton,EmergenceRegistry,neighborhoodRules,StructuralPromoter}from'../src/index.mjs';
const macro=(g)=>({mode:'macro',gate:g,line:1,color:1,tone:1,base:1});const micro=(g,a)=>({mode:'micro',planetary:'sun',dimension:'movement',gate:g,line:1,color:1,tone:1,base:1,degree:0,minute:0,second:0,arc:a,zodiac:1,house:1,scope:'personal',originContext:'test'});
function tool(id,g,kind='bigram'){const sizes={bigram:[2,[1]],trigram:[3,[1,2]],hexagram:[6,[1,2,3,4,5]]};const[s,active]=sizes[kind];return new Automaton({id,address:macro(g),structure:{levelCount:s,minimumActive:active.length},activeLevels:active,functionalLevel:'space',ports:[{id:'in',direction:'input',type:'json'},{id:'out',direction:'output',type:'json'}],implementation:v=>v,metadata:{structuralKind:kind}});}
test('Arc spots remain potential until mapped and neighboring tools arrive',()=>{const r=new EmergenceRegistry({arcRange:{min:1,max:99},neighborhoodRules:[neighborhoodRules.sameArc]});const spot=r.defineSpot({address:micro(1,99)});assert.equal(r.deriveBigram(spot).reason,'ARC_BIGRAM_MAPPING_REQUIRED');const a=tool('a',1),b=tool('b',2);a.address={...a.address,arc:99};b.address={...b.address,arc:99};assert.equal(r.proposeChannel(a,b).status,'candidate');});
test('versioned promotion rules recursively produce trigram, hexagram and decagram Automatons',()=>{const p=new StructuralPromoter();for(const[from,to]of[['bigram','trigram'],['trigram','hexagram'],['hexagram','decagram']])p.register(from,to,(tools)=>({valid:true,operatorVersion:`${from}-${to}.v1`,activeLevels:Array.from({length:({trigram:2,hexagram:5,decagram:9})[to]},(_,i)=>i+1)}));const t=p.promote([tool('b1',1),tool('b2',2)],{address:macro(3)}).automaton;assert.equal(t.metadata.structuralKind,'trigram');const h=p.promote([t,tool('t2',4,'trigram')],{address:macro(5)}).automaton;assert.equal(h.metadata.structuralKind,'hexagram');const d=p.promote([h,tool('h2',6,'hexagram')],{address:macro(7)}).automaton;assert.equal(d.metadata.structuralKind,'decagram');assert.deepEqual(d.metadata.components,[h.id,'h2']);});
test('promotion without a canonical rule stays unresolved instead of guessing',()=>{const p=new StructuralPromoter();assert.equal(p.promote([tool('a',1),tool('b',2)],{address:macro(3)}).reason,'VERSIONED_COMPOSITION_RULE_REQUIRED');});
